plot_love <- function(balance) {
  x<-reshape(balance,direction="long",varying=c("before","after"),v.names="smd",timevar="stage",times=c("Before adjustment","After IPTW"))
  ggplot2::ggplot(x,ggplot2::aes(abs(smd),variable,color=stage))+ggplot2::geom_point(size=3)+ggplot2::geom_vline(xintercept=.1,linetype=2)+ggplot2::labs(title="Covariate Balance",x="Absolute standardized mean difference",y=NULL,color=NULL)+ggplot2::theme_minimal(base_size=12)
}
plot_overlap <- function(d,ps) ggplot2::ggplot(data.frame(ps=ps,treatment=factor(d$treatment,0:1,c("Drug B","Drug A"))),ggplot2::aes(ps,color=treatment,fill=treatment))+ggplot2::geom_density(alpha=.2)+ggplot2::labs(title="Propensity Score Overlap",x="Estimated propensity score",y="Density",color=NULL,fill=NULL)+ggplot2::theme_minimal(base_size=12)
plot_forest <- function(effects,true_ate) ggplot2::ggplot(effects,ggplot2::aes(estimate,reorder(method,estimate)))+ggplot2::geom_vline(xintercept=true_ate,color="#009E73",linetype=2)+ggplot2::geom_errorbar(ggplot2::aes(xmin=lower,xmax=upper),width=.15,orientation="y")+ggplot2::geom_point(size=3,color="#0072B2")+ggplot2::labs(title="Estimated Treatment Effects",subtitle="Dashed line = true simulated ATE",x="Risk difference",y=NULL)+ggplot2::theme_minimal(base_size=12)
plot_bias <- function(effects,true_ate) {x<-effects;x$bias<-x$estimate-true_ate;ggplot2::ggplot(x,ggplot2::aes(bias,reorder(method,bias)))+ggplot2::geom_vline(xintercept=0,linetype=2)+ggplot2::geom_col(fill="#D55E00",width=.65)+ggplot2::labs(title="Bias Relative to the True Simulated Effect",x="Estimated minus true risk difference",y=NULL)+ggplot2::theme_minimal(base_size=12)}
